"""Repository checks. Run before every commit / pull request (CI runs it too).

    python tools/check.py          # report problems
    python tools/check.py --fix    # also regenerate generated files

Checks:
  * Lua syntax of every .lua file (needs luac5.4 / luac)
  * universe data loads and validates (duplicate names, bad routes, ...)
  * the extension index matches verse/extensions/*.lua
  * scenarios: header fields, unique scenario numbers, every place they depend on exists,
    no stock factions (Human Navy / Exuari / Ghosts) in campaign content
  * generated files are up to date (director/generated/world.md, docs/verse_map.svg)
  * the director's Python compiles
"""
from __future__ import annotations

import argparse
import py_compile
import re
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "tools"))
import verse_data  # noqa: E402

INDEX = verse_data.EXT_DIR / "index.lua"
ACTIONS_DIR = ROOT / "ee" / "ragtag" / "director" / "actions"
ACTIONS_INDEX = ACTIONS_DIR / "index.lua"
errors: list[str] = []
warnings: list[str] = []


def extension_index_text() -> str:
    lines = ["-- Generated by tools/check.py --fix / tools/install.py. Do not edit.",
             "-- Loads every universe extension in this folder, alphabetically."]
    for p in verse_data.extension_files():
        lines.append(f'require("ragtag/verse/extensions/{p.name}")')
    return "\n".join(lines) + "\n"


def write_extension_index() -> None:
    INDEX.write_text(extension_index_text())


def action_files() -> list:
    if not ACTIONS_DIR.exists():
        return []
    return sorted(p for p in ACTIONS_DIR.glob("*.lua") if p.name != "index.lua")


def action_index_text() -> str:
    lines = ["-- Generated by tools/check.py --fix / tools/install.py. Do not edit.",
             "-- Loads every director action in this folder, alphabetically."]
    for p in action_files():
        lines.append(f'require("ragtag/director/actions/{p.name}")')
    return "\n".join(lines) + "\n"


def write_action_index() -> None:
    ACTIONS_INDEX.write_text(action_index_text())


def check_lua_syntax() -> None:
    luac = shutil.which("luac5.4") or shutil.which("luac54") or shutil.which("luac")
    if not luac:
        warnings.append("luac not found: skipped Lua syntax check")
        return
    for f in sorted(ROOT.rglob("*.lua")):
        if ".git" in f.parts:
            continue
        r = subprocess.run([luac, "-p", str(f)], capture_output=True, text=True)
        if r.returncode != 0:
            errors.append(f"Lua syntax: {r.stderr.strip()}")


# Patterns that mean "this scenario depends on a universe place".
PLACE_PATTERNS = [
    re.compile(r'VERSE\.at\(\s*"([^"]+)"'),
    re.compile(r'RT\.addStationHook\(\s*"([^"]+)"'),
]
REQUIRE_PLACES = re.compile(r'VERSE\.requirePlaces\(\s*\{([^}]*)\}', re.S)
STOCK_FACTIONS = re.compile(r'"(Human Navy|Exuari|Ghosts)"')
# Scenario numbers used by stock EmptyEpsilon (2024+). Reusing one jumbles the scenario list.
STOCK_NUMBERS = {"00", "02", "03", "05", "06", "07", "08", "10", "20", "27", "29", "30", "31", "32", "33", "34", "39",
                 "44", "47", "48", "49", "50", "51", "53", "54", "55", "56", "57", "58", "59", "60", "62", "74", "79",
                 "81", "88", "99"}


def check_scenarios(places: dict) -> None:
    numbers: dict[str, Path] = {}
    for f in sorted((ROOT / "scenarios").rglob("scenario_*.lua")):
        rel = f.relative_to(ROOT)
        text = f.read_text(encoding="utf-8")
        m = re.match(r"scenario_(\d+)_", f.name)
        if not m:
            errors.append(f"{rel}: name must be scenario_NN_name.lua")
        elif not f.parent.name.startswith("_"):
            if m.group(1) in STOCK_NUMBERS:
                errors.append(f"{rel}: scenario number {m.group(1)} is used by a stock EmptyEpsilon scenario (see CONTRIBUTING.md)")
            if m.group(1) in numbers:
                errors.append(f"{rel}: scenario number {m.group(1)} already used by {numbers[m.group(1)]}")
            numbers[m.group(1)] = rel
        for field in ("Name", "Description", "Type"):
            if not re.search(rf"^-- {field}:", text, re.M):
                errors.append(f"{rel}: missing '-- {field}:' header")
        needed = set()
        for pat in PLACE_PATTERNS:
            needed.update(pat.findall(text))
        declared = set()
        for block in REQUIRE_PLACES.findall(text):
            declared.update(re.findall(r'"([^"]+)"', block))
        for name in sorted(needed | declared):
            if name not in places:
                errors.append(f"{rel}: depends on place '{name}', which the universe doesn't define")
        undeclared = needed - declared
        if undeclared and "VERSE.build" in text:
            warnings.append(f"{rel}: uses {sorted(undeclared)} without listing them in VERSE.requirePlaces")
        if "VERSE.build" in text:
            for fac in sorted(set(STOCK_FACTIONS.findall(text))):
                warnings.append(f"{rel}: uses stock faction '{fac}'; campaign content should use the verse factions")


def check_generated(data: dict, fix: bool) -> None:
    import gen_world
    world = gen_world.render(data)
    if not gen_world.OUT.exists() or gen_world.OUT.read_text() != world:
        if fix:
            gen_world.OUT.parent.mkdir(parents=True, exist_ok=True)
            gen_world.OUT.write_text(world)
            print("regenerated", gen_world.OUT.relative_to(ROOT))
        else:
            errors.append("director/generated/world.md is out of date: run python tools/check.py --fix")
    svg = ROOT / "docs" / "verse_map.svg"
    r = subprocess.run([sys.executable, str(ROOT / "tools" / "make_map.py"), "--stdout"], capture_output=True, text=True)
    if r.returncode != 0:
        errors.append(f"make_map failed: {r.stderr.strip()[-300:]}")
    elif not svg.exists() or svg.read_text() != r.stdout:
        if fix:
            svg.write_text(r.stdout)
            print("regenerated docs/verse_map.svg")
        else:
            errors.append("docs/verse_map.svg is out of date: run python tools/check.py --fix")


def check_python() -> None:
    for f in sorted((ROOT / "director").glob("*.py")) + sorted((ROOT / "tools").glob("*.py")):
        try:
            py_compile.compile(str(f), doraise=True)
        except py_compile.PyCompileError as e:
            errors.append(f"Python: {e.msg}")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--fix", action="store_true", help="regenerate generated files")
    args = ap.parse_args()

    check_lua_syntax()
    current = INDEX.read_text() if INDEX.exists() else ""
    if current != extension_index_text():
        if args.fix:
            write_extension_index()
            print("regenerated", INDEX.relative_to(ROOT))
        else:
            errors.append("verse/extensions/index.lua is out of date: run python tools/check.py --fix")
    current_ai = ACTIONS_INDEX.read_text() if ACTIONS_INDEX.exists() else ""
    if current_ai != action_index_text():
        if args.fix:
            write_action_index()
            print("regenerated", ACTIONS_INDEX.relative_to(ROOT))
        else:
            errors.append("director/actions/index.lua is out of date: run python tools/check.py --fix")
    data = verse_data.load()
    for p in data["problems"]:
        errors.append(f"universe: {p}")
    check_scenarios(data["places"] or {})
    check_generated(data, args.fix)
    check_python()

    for w in warnings:
        print("warning:", w)
    for e in errors:
        print("ERROR:", e)
    print(f"{len(errors)} error(s), {len(warnings)} warning(s). Universe: "
          f"{len(data['stations'])} stations, {len(data['regions'])} regions, extensions: "
          f"{', '.join(e['id'] for e in data['extensions'])}")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
